function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function game_time(int $seconds):string{if($seconds>=86400){$days=intdiv($seconds,86400);return$days.'d '.gmdate('H:i:s',$seconds%86400);}if($seconds>=3600)return gmdate('G:i:s',$seconds);return gmdate('i:s',$seconds);}
function ordinal_word(int $number):string{$words=[1=>'first',2=>'second',3=>'third',4=>'fourth',5=>'fifth',6=>'sixth',7=>'seventh'];return$words[$number]??($number.(in_array($number%100,[11,12,13],true)?'th':([1=>'st',2=>'nd',3=>'rd'][$number%10]??'th')));}
function story_moment(int $seconds,int $duration):string{if($duration<86400)return game_time($seconds);$seconds=min(max(0,$seconds),max(0,$duration-1));$day=intdiv($seconds,86400)+1;$hour=(int)gmdate('G',$seconds%86400);$part=$hour<5?'late at night':($hour<12?'sometime in the morning':($hour<17?'sometime in the afternoon':($hour<22?'sometime in the evening':'late at night')));return'On the '.ordinal_word($day).' day, '.$part;}
function story_phase_label(string $phase):string{return['EXPOSITION'=>'The Story Begins','INCITING_INCIDENT'=>'Trouble Emerges','RISING_ACTION'=>'Pressure Builds','CLIMAX'=>'The Decisive Moment','RESOLUTION'=>'Consequences Settle','COMPLETE'=>'Consequences Settle'][$phase]??ucwords(strtolower(str_replace('_',' ',$phase)));}
function story_phase_for_second(int $second,int $duration):string{$ratio=$duration>0?$second/$duration:1;return$ratio<.18?'EXPOSITION':($ratio<.42?'INCITING_INCIDENT':($ratio<.72?'RISING_ACTION':($ratio<.92?'CLIMAX':'RESOLUTION')));}
function personal_experience_label(string $type):string{return['DECISION'=>'What You Did','NO_ACTION'=>'What You Left Undone','LOCATION'=>'Where You Went','KNOWLEDGE'=>'What You Learned','CONSEQUENCE'=>'What Changed for You','INTERACTION'=>'What You Considered','EXPERIENCED'=>'Your Point of View'][$type]??'Your Point of View';}
function timeline_fingerprint(string $text):string{$text=mb_strtolower(strip_tags($text));$text=preg_replace('/[^\p{L}\p{N}]+/u',' ',$text);return trim((string)$text);}
function player_visible_text(string $text):string{$text=preg_replace('/\\s*Final factors:\\s*[^.!?]+[.!?]?/ui','',$text);$text=preg_replace('/\s*(?:Location|Goal|Fear)\s*→\s*[^.!?]+[.!?]?/ui','',$text);$sentences=preg_split('/(?<=[.!?])\s+/u',trim((string)$text))?:[];$sentences=array_values(array_filter($sentences,static fn($sentence)=>!preg_match('/\d+\s*→\s*\d+/u',$sentence)));return trim(implode(' ',$sentences));}
function missed_opportunity_text(array $labels):string{$labels=array_values(array_filter(array_map(static fn($label)=>lcfirst(rtrim(trim((string)$label),'.')),$labels)));if(!$labels)return'You were given a chance to act, but you decided not to before the situation changed.';$last=array_pop($labels);$choices=$last??'act';if($labels)$choices=implode(', ',$labels).(count($labels)>1?', or ':' or ').$choices;return'You were given the chance to '.$choices.', but you decided not to act before the situation changed.';}
function past_verb(string $verb):string{$lower=strtolower($verb);$map=['am'=>'was','are'=>'were','is'=>'was','begin'=>'began','break'=>'broke','bring'=>'brought','build'=>'built','choose'=>'chose','come'=>'came','cut'=>'cut','cuts'=>'cut','do'=>'did','draw'=>'drew','drink'=>'drank','drive'=>'drove','feel'=>'felt','find'=>'found','flee'=>'fled','get'=>'got','give'=>'gave','go'=>'went','has'=>'had','have'=>'had','hear'=>'heard','hears'=>'heard','head'=>'headed','heads'=>'headed','hold'=>'held','keep'=>'kept','know'=>'knew','lead'=>'led','leave'=>'left','make'=>'made','meet'=>'met','move'=>'moved','moves'=>'moved','notice'=>'noticed','notices'=>'noticed','put'=>'put','read'=>'read','reach'=>'reached','reaches'=>'reached','run'=>'ran','say'=>'said','see'=>'saw','seek'=>'sought','send'=>'sent','sit'=>'sat','speak'=>'spoke','stand'=>'stood','study'=>'studied','take'=>'took','tell'=>'told','think'=>'thought','write'=>'wrote'];if(isset($map[$lower]))return$map[$lower];if(preg_match('/ed$/',$lower))return$lower;if(preg_match('/[^aeiou]y$/',$lower))return substr($lower,0,-1).'ied';if(preg_match('/e$/',$lower))return$lower.'d';return$lower.'ed';}
function character_pronouns(array $character):array{$set=strtoupper((string)($character['pronoun_set']??'IT'));return$set==='HE'?['he','him','his']:($set==='SHE'?['she','her','her']:['it','it','its']);}
function observer_narrative(array $actor,string $text):string{$name=(string)($actor['name']??'Someone');[$subject,$object,$possessive]=character_pronouns($actor);if($text==='')return$name.' acted while the situation continued to change.';$text=preg_replace('/^Your\\b/u',ucfirst($possessive),$text);if(preg_match('/^You\\s+([A-Za-z]+)(.*)$/su',$text,$m))$text=$name.' '.past_verb($m[1]).$m[2];$text=preg_replace('/\\b[Yy]our\\b/u',$possessive,$text);$text=preg_replace('/\\b[Yy]ou\\b/u',$name,$text);$first=true;$text=preg_replace_callback('/\\b'.preg_quote($name,'/').'\\b/u',static function($m)use(&$first,$subject){if($first){$first=false;return$m[0];}return$subject;},$text);$verbs=['begin','cuts','hear','hears','head','heads','move','moves','notice','notices','reach','reaches'];$pattern='/\\b('.implode('|',$verbs).')\\b/i';return preg_replace_callback($pattern,static fn($m)=>past_verb($m[1]),$text);}
function player_pov_narrative(array $character,string $text):string{if($text==='')return$text;$name=(string)($character['name']??'');[$subject,$object,$possessive]=character_pronouns($character);if($name!=='')$text=preg_replace('/\\b'.preg_quote($name,'/').'\\b/u','you',$text);$text=preg_replace('/\\b'.preg_quote($possessive,'/').'\\b/ui','your',$text);$text=preg_replace('/\\b(?:'.preg_quote($subject,'/').'|'.preg_quote($object,'/').')\\b/ui','you',$text);return preg_replace('/^you\\b/u','You',$text);}
